selected.compute:
options = read('/input/options')
ids = []
for r in options:
    ids = ids + [r['id']]
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(ids, k):
        candidate = list(group)
        if valid(candidate):
            ordered = []
            remaining = list(candidate)
            for r in sorted(options, key=lambda x: (x['rank'], x['id'])):
                if r['id'] in remaining:
                    ordered = ordered + [r['id']]
            result = ordered
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
else:
    current = result
    write('/output/selection', current)
if status('report') == 'not_sent':
    send('report', 'team', current)
if exists('/tmp/cache'):
    delete('/tmp/cache')
